def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    my_last = my[-1]
    opp_last = opp[-1]

    opp_defects = opp.count('D')
    my_defects = my.count('D')

    if n >= 98 and opp_defects == 0:
        return 'D'

    if opp_last == 'D':
        if opp_defects >= 2 and opp_defects * 2 >= n:
            return 'D'
        if opp_defects <= 2 and n > 5:
            return 'C'
        if my_last == 'D':
            return 'C'
        return 'D'

    punishments = 0
    last_defect = -1
    for i in range(n - 1):
        if my[i] == 'D':
            last_defect = i
            if opp[i+1] == 'D':
                punishments += 1

    since_last = n - last_defect if last_defect >= 0 else n + 1

    if punishments >= 3:
        allowed = False
    elif punishments == 2:
        allowed = since_last > 15
    elif punishments == 1:
        allowed = since_last > 8
    else:
        allowed = since_last > 4

    if allowed:
        return 'D'
    else:
        return 'C'
